#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std; using boost::multiprecision::cpp_int; using u128=unsigned __int128;
struct Pt{int x,y; bool operator<(Pt const&o)const{return tie(x,y)<tie(o.x,o.y);} bool operator==(Pt const&o)const{return x==o.x&&y==o.y;}};
struct Lab{int k; Pt a,b;};
vector<Pt>P,Core; map<pair<int,int>,int> PI,CI; vector<unsigned long long>P3; vector<Lab>Old,New; int TI[6];
int gv(uint64_t s,int i){return (s/P3[i])%3;} uint64_t sv(uint64_t s,int i,int v){return s+(long long)(v-gv(s,i))*P3[i];}
set<Pt> nb(Pt p){return {{p.x+1,p.y},{p.x-1,p.y},{p.x,p.y+1},{p.x,p.y-1}};}
vector<int> niP(Pt p){vector<int>r;for(auto q:nb(p)){auto it=PI.find({q.x,q.y});if(it!=PI.end())r.push_back(it->second);}return r;}
bool adj(Pt a,Pt b){return abs(a.x-b.x)+abs(a.y-b.y)==1;}
bool insideP(Pt p){return PI.count({p.x,p.y});}
bool suppcoP(Pt p){if(!insideP(p))return false;for(auto q:nb(p))if(!insideP(q))return false;return true;}
bool suppoP(Pt a,Pt b){if(!insideP(a)||!insideP(b)||!adj(a,b))return false;for(auto q:nb(a))if(!insideP(q))return false;for(auto q:nb(b))if(!insideP(q))return false;return true;}
vector<pair<uint64_t,int>> trP(uint64_t s, Lab l){map<uint64_t,int>o;if(!l.k){int i=PI[{l.a.x,l.a.y}];if(gv(s,i))return{{s,72}};auto a=sv(s,i,1);vector<int>os;for(int q:niP(l.a))if(gv(a,q)==2)os.push_back(q);if(os.empty())return{{a,72}};int w=72/os.size();for(int q:os)o[sv(sv(a,i,0),q,0)]+=w;}else{int u=PI[{l.a.x,l.a.y}],v=PI[{l.b.x,l.b.y}];if(gv(s,u)||gv(s,v))return{{s,36}};auto a=sv(sv(s,u,2),v,2);vector<int>cu,cv;for(int q:niP(l.a))if(gv(a,q)==1)cu.push_back(q);for(int q:niP(l.b))if(gv(a,q)==1)cv.push_back(q);if(cu.empty())cu.push_back(-1);if(cv.empty())cv.push_back(-1);int d=cu.size()*cv.size(); if(36%d){cerr<<"bad den\n";exit(2);}int w=36/d;for(int qu:cu)for(int qv:cv){auto t=a;if(qu>=0)t=sv(sv(t,u,0),qu,0);if(qv>=0)t=sv(sv(t,v,0),qv,0);o[t]+=w;}}return{o.begin(),o.end()};}
uint64_t embedCore(uint64_t cs, const array<int,4>& bv){uint64_t s=0; for(int i=0;i<(int)Core.size();i++){int v=(cs/P3[i])%3; s+=P3[PI[{Core[i].x,Core[i].y}]]*v;} vector<Pt> E={{0,-2},{0,3},{1,2},{2,1}}; for(int j=0;j<4;j++)s+=P3[PI[{E[j].x,E[j].y}]]*bv[j]; return s;}
uint64_t projCore(uint64_t ps){uint64_t c=0;for(int i=0;i<(int)Core.size();i++)c+=P3[i]*gv(ps,PI[{Core[i].x,Core[i].y}]);return c;}
bool stableP(uint64_t s){for(int i=0;i<(int)P.size();i++){int a=gv(s,i); if(!a)continue; for(auto q:nb(P[i])){auto it=PI.find({q.x,q.y}); if(it==PI.end())continue; int j=it->second; if(j<=i)continue;int b=gv(s,j);if((a==1&&b==2)||(a==2&&b==1))return false;}}return true;}
bool targetC(uint64_t cs){for(int i:TI)if((cs/P3[i])%3)return false;return true;}
unordered_map<uint64_t,u128> M[9];
u128 V(int n,uint64_t cs){auto &m=M[n];auto it=m.find(cs);if(it!=m.end())return it->second; if(!n){u128 z=targetC(cs);m.emplace(cs,z);return z;} array<int,4> zero={0,0,0,0}; uint64_t ps0=embedCore(cs,zero); u128 oldsum=0; for(auto const&l:Old)for(auto [pt,w]:trP(ps0,l))oldsum+=(u128)w*V(n-1,projCore(pt)); bool any=false; u128 best=~(u128)0; for(int code=0;code<81;code++){int q=code;array<int,4>b;for(int j=0;j<4;j++){b[j]=q%3;q/=3;}uint64_t ps=embedCore(cs,b);if(!stableP(ps))continue;any=true;u128 z=0;for(auto const&l:New)for(auto [pt,w]:trP(ps,l))z+=(u128)w*V(n-1,projCore(pt));if(z<best)best=z;} if(!any){cerr<<"no stable extension\n";exit(3);}u128 z=oldsum+best;m.emplace(cs,z);return z;}
string s128(u128 x){if(!x)return"0";string s;while(x){s.push_back('0'+x%10);x/=10;}reverse(s.begin(),s.end());return s;}cpp_int pw(cpp_int a,int n){cpp_int r=1;while(n--)r*=a;return r;}
int main(){vector<pair<int,int>> core={{-2,0},{-2,1},{-1,-1},{-1,0},{-1,1},{-1,2},{0,-1},{0,0},{0,1},{0,2},{1,-1},{1,0},{1,1},{2,0}};vector<pair<int,int>> extras={{0,-2},{0,3},{1,2},{2,1}};for(auto[x,y]:core)Core.push_back({x,y});sort(Core.begin(),Core.end());vector<pair<int,int>> pp=core;for(auto e:extras)pp.push_back(e);sort(pp.begin(),pp.end());pp.erase(unique(pp.begin(),pp.end()),pp.end());for(auto[x,y]:pp)P.push_back({x,y});for(int i=0;i<(int)P.size();i++)PI[{P[i].x,P[i].y}]=i;for(int i=0;i<(int)Core.size();i++)CI[{Core[i].x,Core[i].y}]=i;P3.resize(30);P3[0]=1;for(int i=1;i<30;i++)P3[i]=P3[i-1]*3ULL;
 set<pair<int,int>> BC(core.begin(),core.end()); auto inC=[&](Pt p){return BC.count({p.x,p.y});}; auto sco=[&](Pt p){if(!inC(p))return false;for(auto q:nb(p))if(!inC(q))return false;return true;}; auto so2=[&](Pt a,Pt b){if(!inC(a)||!inC(b)||!adj(a,b))return false;for(auto q:nb(a))if(!inC(q))return false;for(auto q:nb(b))if(!inC(q))return false;return true;};
 for(auto p:P)if(sco(p))Old.push_back({0,p,{0,0}});set<pair<Pt,Pt>>seen;for(auto p:P)for(auto q:nb(p)){Pt a=p,b=q;if(b<a)swap(a,b);if(seen.insert({a,b}).second&&so2(a,b))Old.push_back({1,a,b});}
 vector<Lab>All;for(auto p:P)if(suppcoP(p))All.push_back({0,p,{0,0}});seen.clear();for(auto p:P)for(auto q:nb(p)){Pt a=p,b=q;if(b<a)swap(a,b);if(seen.insert({a,b}).second&&suppoP(a,b))All.push_back({1,a,b});}auto same=[](Lab u,Lab v){return u.k==v.k&&u.a==v.a&&(u.k==0||u.b==v.b);};for(auto a:All){bool old=false;for(auto b:Old)if(same(a,b)){old=true;break;}if(!old)New.push_back(a);}if(Old.size()!=10||New.size()!=7){cerr<<"labels "<<Old.size()<<" "<<New.size()<<"\n";return 4;}
 vector<pair<int,int>> targ={{-1,0},{-1,1},{0,0},{0,1},{1,0},{1,1}};for(int j=0;j<6;j++)TI[j]=CI[targ[j]];
 vector<pair<int,int>> CEL={{-2,0},{-2,1},{-1,-1},{-1,0},{-1,1},{-1,2},{0,-1},{0,0},{0,1},{0,2},{1,-1},{1,0},{1,1},{1,2},{2,0},{2,1}};map<pair<int,int>,int> EI;for(int i=0;i<(int)CEL.size();i++)EI[CEL[i]]=i;set<pair<int,int>> fixed={{-2,0},{-2,1},{-1,0},{-1,1},{0,0},{0,1}};vector<int>var;for(int i=0;i<(int)CEL.size();i++)if(!fixed.count(CEL[i]))var.push_back(i);set<uint64_t> init; long long full=0,tot=1;for(int _:var)tot*=3;for(long long code=0;code<tot;code++){long long q=code;vector<int>x(CEL.size(),0);for(int i:var){x[i]=q%3;q/=3;}bool ok=true;for(int i=0;i<(int)CEL.size()&&ok;i++){for(auto d:vector<pair<int,int>>{{1,0},{0,1}}){auto it=EI.find({CEL[i].first+d.first,CEL[i].second+d.second});if(it!=EI.end()&&((x[i]==1&&x[it->second]==2)||(x[i]==2&&x[it->second]==1))){ok=false;break;}}}if(!ok)continue;full++;uint64_t cs=0;for(int i=0;i<(int)Core.size();i++){auto c=make_pair(Core[i].x,Core[i].y);cs+=P3[i]*x[EI[c]];}init.insert(cs);}if(full!=7255||init.size()!=1743){cerr<<"entrance "<<full<<" "<<init.size()<<"\n";return 5;}
 cpp_int aa=429,bb=200,H=36*214;unsigned long long fact[9];fact[0]=1;for(int n=1;n<=8;n++)fact[n]=fact[n-1]*n;vector<cpp_int>cf(9);for(int n=0;n<=8;n++)cf[n]=pw(aa,n)*pw(bb,8-n)*pw(H,8-n)*(fact[8]/fact[n]);bool first=true;cpp_int best;uint64_t arg=0;vector<u128>mins(9,~(u128)0),bas(9);for(auto cs:init){cpp_int num=0;vector<u128>a(9);for(int n=0;n<=8;n++){a[n]=V(n,cs);if(a[n]<mins[n])mins[n]=a[n];num+=cpp_int(s128(a[n]))*cf[n];}if(first||num<best){first=false;best=num;arg=cs;bas=a;}}
 cout<<"PASS exact R08/E0011 adversarial-boundary Bellman DP\n"<<"entrance_full="<<full<<" descriptors="<<init.size()<<" old_labels="<<Old.size()<<" new_labels="<<New.size()<<"\n"<<"worst="<<arg<<"\nMINS=";for(int n=0;n<=8;n++)cout<<s128(mins[n])<<(n<8?",":"\n");cout<<"WORST_A=";for(int n=0;n<=8;n++)cout<<s128(bas[n])<<(n<8?",":"\n");cout<<"ROBUST_POLY_NUM="<<best<<"\nROBUST_POLY_DEN="<<pw(bb,8)*pw(H,8)*fact[8]<<"\n";
}
